create table categorias (estado boolean not null, fecha_creacion timestamp(9) not null, fecha_modificacion timestamp(9) not null, id number(19,0) generated by default as identity, nombre varchar2(50 char) not null, descripcion varchar2(200 char), primary key (id));
create table clientes (estado boolean not null, dni varchar2(8 char) not null, fecha_creacion timestamp(9) not null, fecha_modificación timestamp(9), id number(19,0) generated by default as identity, telefono varchar2(15 char), apellidos varchar2(100 char) not null, nombres varchar2(100 char) not null, email varchar2(150 char) not null, direccion varchar2(250 char), primary key (id));
create table detalle_venta (cantidad number(10,0) not null, precio number(10,2) not null, subtotal number(12,2) not null, id number(19,0) generated by default as identity, producto_id number(19,0) not null, venta_id number(19,0) not null, primary key (id));
create table empleados (estado boolean not null, dni varchar2(8 char) not null unique, fecha_creacion timestamp(9) not null, fecha_modificacion timestamp(9), id number(19,0) generated by default as identity, telefono varchar2(15 char), cargo varchar2(60 char) not null, apellidos varchar2(100 char) not null, nombres varchar2(100 char) not null, email varchar2(150 char) not null unique, primary key (id));
create table producto (estado boolean not null, precio number(38,2) not null, stock number(10,0) not null, categoria_id number(19,0) not null, fecha_creacion timestamp(9) not null, fecha_modificacion timestamp(9), id number(19,0) generated by default as identity, nombre varchar2(150 char) not null, primary key (id));
create table roles (id number(19,0) generated by default as identity, nombre varchar2(30 char) not null unique, descripcion varchar2(150 char), primary key (id));
create table usuario_roles (rol_id number(19,0) not null, usuario_id number(19,0) not null, primary key (rol_id, usuario_id));
create table usuarios (estado boolean not null, empleado_id number(19,0) not null unique, fecha_creacion timestamp(9) not null, fecha_modificacion timestamp(9), id number(19,0) generated by default as identity, username varchar2(50 char) not null unique, password varchar2(100 char) not null, primary key (id));
create table ventas (total number(12,2) not null, cliente_id number(19,0) not null, fecha timestamp(9) not null, id number(19,0) generated by default as identity, estado varchar2(20 char) not null check ((estado in ('REGISTRADA','ANULADA'))), primary key (id));
